#include <hip/hip_runtime.h>
#include <math.h>

template<typename T>
__global__ void maxpool2d_kernel(
    const T* __restrict__ input,
    T* __restrict__ output,
    const int batch_size,
    const int channels,
    const int input_height,
    const int input_width,
    const int output_height,
    const int output_width,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation
) {
    // Use 4D indexing: x (width), y (height), z (batch, channel)
    int output_x = blockIdx.x * blockDim.x + threadIdx.x;
    int output_y = blockIdx.y * blockDim.y + threadIdx.y;
    int linear_z = blockIdx.z * blockDim.z + threadIdx.z;

    int b = linear_z / channels;
    int c = linear_z % channels;

    if (output_x >= output_width || output_y >= output_height || b >= batch_size) {
        return;
    }

    // Calculate the top-left corner of the pooling window in input
    const int input_start_x = output_x * stride - padding;
    const int input_start_y = output_y * stride - padding;

    // Initialize max value to negative infinity
    T max_val = -INFINITY;

    // Pre-compute row offset for better memory access
    const int batch_channel_offset = b * channels * input_height * input_width 
                                   + c * input_height * input_width;

    // Iterate over the kernel window
    #pragma unroll
    for (int ky = 0; ky < kernel_size; ++ky) {
        const int input_y = input_start_y + ky * dilation;
        // Bounds check for y
        if (input_y < 0 || input_y >= input_height) continue;

        // Pre-compute row pointer
        const int row_offset = batch_channel_offset + input_y * input_width;

        #pragma unroll
        for (int kx = 0; kx < kernel_size; ++kx) {
            const int input_x = input_start_x + kx * dilation;
            // Bounds check for x
            if (input_x < 0 || input_x >= input_width) continue;

            // Compute input index and load value
            const int input_idx = row_offset + input_x;
            T val = input[input_idx];
            if (val > max_val) {
                max_val = val;
            }
        }
    }

    // Compute output index and store the result
    const int output_idx = b * channels * output_height * output_width 
                          + c * output_height * output_width 
                          + output_y * output_width 
                          + output_x;
    output[output_idx] = max_val;
}

template<typename T>
__global__ void maxpool2d_kernel_optimized(
    const T* __restrict__ input,
    T* __restrict__ output,
    const int batch_size,
    const int channels,
    const int input_height,
    const int input_width,
    const int output_height,
    const int output_width,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation
) {
    // Process multiple output elements per thread (x-dimension vectorization)
    const int VEC_X = 4;

    int output_x_base = blockIdx.x * blockDim.x * VEC_X + threadIdx.x;
    int output_y = blockIdx.y * blockDim.y + threadIdx.y;
    int linear_z = blockIdx.z * blockDim.z + threadIdx.z;

    int b = linear_z / channels;
    int c = linear_z % channels;

    if (output_y >= output_height || b >= batch_size) {
        return;
    }

    // Pre-compute base offsets
    const int batch_channel_offset_in = b * channels * input_height * input_width 
                                        + c * input_height * input_width;
    const int batch_channel_offset_out = b * channels * output_height * output_width 
                                         + c * output_height * output_width 
                                         + output_y * output_width;

    // Process VEC_X output elements
    #pragma unroll
    for (int v = 0; v < VEC_X; ++v) {
        int output_x = output_x_base + v * blockDim.x;
        if (output_x >= output_width) continue;

        // Calculate the top-left corner of the pooling window in input
        const int input_start_x = output_x * stride - padding;
        const int input_start_y = output_y * stride - padding;

        // Initialize max value to negative infinity
        T max_val = -INFINITY;

        // Iterate over the kernel window
        #pragma unroll
        for (int ky = 0; ky < kernel_size; ++ky) {
            const int input_y = input_start_y + ky * dilation;
            if (input_y < 0 || input_y >= input_height) continue;

            const int row_offset = batch_channel_offset_in + input_y * input_width;

            #pragma unroll
            for (int kx = 0; kx < kernel_size; ++kx) {
                const int input_x = input_start_x + kx * dilation;
                if (input_x < 0 || input_x >= input_width) continue;

                const int input_idx = row_offset + input_x;
                T val = input[input_idx];
                if (val > max_val) {
                    max_val = val;
                }
            }
        }

        // Store the result
        output[batch_channel_offset_out + output_x] = max_val;
    }
}

torch::Tensor maxpool2d_hip(torch::Tensor input, int kernel_size, int stride, int padding, int dilation) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto input_height = input.size(2);
    auto input_width = input.size(3);

    // Calculate output dimensions
    int output_height = (input_height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int output_width = (input_width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, channels, output_height, output_width}, input.options());

    const int TILE_X = 16;
    const int TILE_Y = 16;
    const int VEC_X = 4;
    const int TILE_Z = 1;

    dim3 block(TILE_X, TILE_Y, TILE_Z);

    dim3 grid;
    grid.x = (output_width + TILE_X * VEC_X - 1) / (TILE_X * VEC_X);
    grid.y = (output_height + TILE_Y - 1) / TILE_Y;
    grid.z = (batch_size * channels + TILE_Z - 1) / TILE_Z;

    maxpool2d_kernel_optimized<float><<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        input_height,
        input_width,
        output_height,
        output_width,
        kernel_size,
        stride,
        padding,
        dilation
    );

    return output;
}
