#include <hip/hip_runtime.h>
#include <math.h>

// Shared memory-based maxpool with caching
template<typename T>
__global__ void maxpool2d_kernel_tiled(
    const T* __restrict__ input,
    T* __restrict__ output,
    const int batch_size,
    const int channels,
    const int input_height,
    const int input_width,
    const int output_height,
    const int output_width,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation
) {
    // Tiling parameters
    const int TILE_SIZE = 16;

    // For a 4x4 kernel with dilation=1 and padding=1, stride=1
    // We need to load a larger tile to account for the kernel window
    const int LOAD_TILE_SIZE = TILE_SIZE + kernel_size + 2 * padding;  // Conservative estimate

    __shared__ T shared_input[TILE_SIZE][TILE_SIZE];

    // Thread and block indices
    int thread_x = threadIdx.x;
    int thread_y = threadIdx.y;

    int output_x_start = blockIdx.x * TILE_SIZE;
    int output_y_start = blockIdx.y * TILE_SIZE;

    int batch = blockIdx.z / channels;
    int channel = blockIdx.z % channels;

    if (batch >= batch_size) return;

    // Each thread loads one element from input to shared memory
    // Calculate global input coordinates
    int input_x = output_x_start + thread_x * stride - padding;
    int input_y = output_y_start + thread_y * stride - padding;

    // Load element into shared memory
    if (thread_x < TILE_SIZE && thread_y < TILE_SIZE) {
        if (input_x >= 0 && input_x < input_width && input_y >= 0 && input_y < input_height) {
            int input_idx = batch * channels * input_height * input_width 
                          + channel * input_height * input_width 
                          + input_y * input_width 
                          + input_x;
            shared_input[thread_y][thread_x] = input[input_idx];
        } else {
            // Pad with negative infinity (will be ignored in max)
            shared_input[thread_y][thread_x] = -INFINITY;
        }
    }

    __syncthreads();

    // Compute maxpool for this thread's output position
    int output_x = output_x_start + thread_x;
    int output_y = output_y_start + thread_y;

    if (output_x < output_width && output_y < output_height) {
        // Find in shared memory the index of our top-left corner
        int shared_start_x = thread_x - padding;
        int shared_start_y = thread_y - padding;

        T max_val = -INFINITY;

        // Unroll loop for kernel iterations (4x4 kernel)
        #pragma unroll
        for (int ky = 0; ky < kernel_size; ++ky) {
            int sy = shared_start_y + ky * dilation;
            if (sy < 0 || sy >= TILE_SIZE) continue;

            #pragma unroll
            for (int kx = 0; kx < kernel_size; ++kx) {
                int sx = shared_start_x + kx * dilation;
                if (sx < 0 || sx >= TILE_SIZE) continue;

                T val = shared_input[sy][sx];
                if (val > max_val) {
                    max_val = val;
                }
            }
        }

        // Write output
        int output_idx = batch * channels * output_height * output_width 
                         + channel * output_height * output_width 
                         + output_y * output_width 
                         + output_x;
        output[output_idx] = max_val;
    }
}

// Streamlined direct kernel without shared memory
template<typename T>
__global__ void maxpool2d_kernel_direct(
    const T* __restrict__ input,
    T* __restrict__ output,
    const int batch_size,
    const int channels,
    const int input_height,
    const int input_width,
    const int output_height,
    const int output_width,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation
) {
    int output_x = blockIdx.x * blockDim.x + threadIdx.x;
    int output_y = blockIdx.y * blockDim.y + threadIdx.y;
    int batch = blockIdx.z / channels;
    int channel = blockIdx.z % channels;

    if (output_x >= output_width || output_y >= output_height || batch >= batch_size) {
        return;
    }

    const int input_start_x = output_x * stride - padding;
    const int input_start_y = output_y * stride - padding;

    T max_val = -INFINITY;

    // Precompute strides
    const int input_bc_stride = input_height * input_width;
    const int output_bc_stride = output_height * output_width;

    // Base offsets
    const int input_base = batch * channels * input_bc_stride + channel * input_bc_stride;

    // Unrolled kernel iteration for 4x4 case
    #pragma unroll
    for (int ky = 0; ky < kernel_size; ++ky) {
        int input_y = input_start_y + ky * dilation;
        if (input_y < 0 || input_y >= input_height) continue;

        const int row_start = input_base + input_y * input_width;

        #pragma unroll
        for (int kx = 0; kx < kernel_size; ++kx) {
            int input_x = input_start_x + kx * dilation;
            if (input_x < 0 || input_x >= input_width) continue;

            T val = input[row_start + input_x];
            if (val > max_val) {
                max_val = val;
            }
        }
    }

    const int output_base = batch * channels * output_bc_stride + channel * output_bc_stride;
