    dim3 block(BLOCK_X, BLOCK_Y, BLOCK_Z);

    dim3 grid;
    grid.x = (output_width + BLOCK_X - 1) / BLOCK_X;
    grid.y = (output_height + BLOCK_Y - 1) / BLOCK_Y;
    grid.z = (batch_size * channels + BLOCK_Z - 1) / BLOCK_Z;

